def extras(pid, tier, lang, existing=''):
    s = SLOTS[lang]; st = '_' + pid if pid in ('stella', 'lilia') else ''
    out = []
    for x in (EXTRAS_LILIA if pid == 'lilia' else EXTRAS)[lang][tier]:
        x = x.replace('{ch}', s['ch' + st]).replace('{handover}', s['handover' + st]).replace('{k}', KNOW[lang][pid])
        if x == '{ci}':
            if 'custom integrations' in existing.lower() or 'تكاملات مخصصة' in existing: continue
            x = s['ci']
        if x == '{dam}':
            if 'account manager' in existing.lower() or 'مدير حساب' in existing: continue
            x = s['dam']
        out.append(x)
    return out

